<script setup>
import {shallowRef,ref,onBeforeUnmount,watch,nextTick} from 'vue';import {Button,Field,Checkbox,Cell,Popup,Picker} from 'vant';
import 'vant/es/button/style';import 'vant/es/field/style';import 'vant/es/checkbox/style';import 'vant/es/cell/style';import 'vant/es/popup/style';import 'vant/es/picker/style';
const {controller}=defineProps({controller:{type:Object,required:true}}),m=shallowRef(controller.snapshot()),a=controller.actions,off=controller.subscribe(v=>m.value=v),picker=ref(false),root=ref(),failed=ref('');onBeforeUnmount(off);
watch(root,()=>nextTick(()=>{const el=root.value?.$el||root.value;if(el)a.attach(el);}));
function invoke(type,event){try{const value=a.fire(type,event);if(value?.catch)value.catch(e=>failed.value=e.message);}catch(e){failed.value=e.message;}}
function select({selectedValues}){a.value(selectedValues[0]);picker.value=false;a.change();}
const attrs=()=>Object.fromEntries(Object.entries(m.value.attributes).filter(([key])=>!['class','style','type','value','checked','disabled','hidden'].includes(key)));
</script>
<template><template v-if="!m.hidden"><Button v-if="m.kind==='button'" ref="root" v-bind="attrs()" :class="m.classes" :style="m.style" :disabled="m.disabled" :native-type="m.type==='submit'?'submit':'button'" @click="invoke('click',$event)" @dblclick="invoke('dblclick',$event)" @pointerdown="invoke('pointerdown',$event)" @pointermove="invoke('pointermove',$event)" @pointerup="invoke('pointerup',$event)" @pointercancel="invoke('pointercancel',$event)" @lostpointercapture="invoke('lostpointercapture',$event)" @keydown="invoke('keydown',$event)"><img v-if="m.image" :src="m.image" alt="" draggable="false"/><span v-else-if="/^(×|✕|✖|X)$/.test(m.text)" class="duck-cross" aria-hidden="true">×</span><template v-else>{{m.text||m.attributes['aria-label']}}</template></Button><Checkbox v-else-if="m.kind==='checkbox'" ref="root" v-bind="attrs()" :class="m.classes" :style="m.style" :model-value="m.checked" :disabled="m.disabled" @update:model-value="v=>{a.checked(v);invoke('change')}"/><template v-else-if="m.kind==='select'"><Cell ref="root" v-bind="attrs()" :class="m.classes" :style="m.style" :value="m.options.find(o=>String(o.value)===String(m.value))?.text||'请选择'" :aria-label="m.attributes['aria-label']||m.attributes.name||'选择'" is-link :clickable="!m.disabled" @click="!m.disabled&&(picker=true)"/><Popup v-model:show="picker" position="bottom" round teleport="body" class="duck-control-picker"><header><h3>{{m.attributes['aria-label']||'选择'}}</h3><Button icon="cross" aria-label="关闭选择" @click="picker=false"/></header><Picker :columns="m.options" :model-value="[m.value]" @confirm="select"><template #cancel><Button icon="cross" aria-label="关闭选择" @click="picker=false"/></template></Picker></Popup></template><Field v-else ref="root" v-bind="attrs()" :class="m.classes" :style="m.style" :type="m.tag==='textarea'?'textarea':m.type==='password'?'password':m.type==='number'?'number':'text'" :model-value="m.value" :disabled="m.disabled" :readonly="m.readOnly" :autosize="m.tag==='textarea'" @update:model-value="v=>a.value(v)" @input="invoke('input',$event)" @change="invoke('change',$event)" @keydown="invoke('keydown',$event)"/><span v-if="failed" role="alert">{{failed}}</span></template></template>
<style>.duck-vue-control{display:contents}</style>
<style scoped>
.van-button.course-duck-launch{width:88px;height:88px;padding:0;border:0;border-radius:35%;background:transparent;box-shadow:none}
.van-button.course-duck-launch img{width:calc(208px / 3);height:80px}
@media(max-width:520px){.van-button.course-duck-launch img{width:calc(172px / 3);height:calc(200px / 3)}}
</style>
<style scoped>.van-button :deep(.van-button__text){width:auto!important;margin:0!important;font-size:inherit!important;white-space:normal}.van-button.swatch :deep(.van-button__text){font-size:0!important}.van-button.swatch{padding:0;border:0;border-radius:50%;background:var(--swatch)}:global(.actions) .van-button{font-size:11px;line-height:1.4;height:auto;min-height:44px;padding:8px 3px}.van-button{min-width:44px;min-height:44px;font:inherit}.duck-cross{font-size:28px;line-height:1}.van-button img{display:block;max-width:100%;height:auto}.van-field{max-width:100%;font:inherit}.van-field :deep(.van-field__control){border:0;box-shadow:none;padding:0;min-height:0;font:inherit;background:transparent}.van-cell{min-height:44px;max-width:100%;font:inherit}.duck-control-picker header{display:flex;align-items:center;justify-content:space-between;padding:12px 18px;gap:12px}.duck-control-picker header h3{font-size:18px;margin:0}.duck-control-picker header .van-button{width:44px;padding:0}.duck-control-picker :deep(.van-picker__confirm){min-height:44px}</style>
